import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str):
    expected_width = 9
    delimiter = ","
    quotechar = '"'

    if not raw_csv:
        return {"columns": [], "rows": []}

    try:
        reader = csv.reader(
            io.StringIO(raw_csv),
            delimiter=delimiter,
            quotechar=quotechar,
            doublequote=True,
            strict=False,
        )
        parsed = [list(row) for row in reader]
    except (csv.Error, TypeError, ValueError):
        parsed = []
        for line in raw_csv.splitlines():
            parsed.append(line.split(delimiter))

    def nonempty(row):
        return bool(row) and any(str(value).strip() for value in row)

    def date_like(value):
        value = str(value).strip()
        return bool(
            re.match(
                r"^\d{1,4}[-/]\d{1,2}[-/]\d{1,4}(?:[ T]\d{1,2}:\d{2}(?::\d{2})?)?$",
                value,
            )
        )

    def numeric_like(value):
        value = str(value).strip()
        return bool(re.match(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$", value))

    def header_score(index, row):
        values = [str(value).strip() for value in row]
        nonempty_values = [value for value in values if value]
        if not nonempty_values:
            return -1000

        score = 0
        alpha_count = sum(bool(re.search(r"[A-Za-z]", value)) for value in nonempty_values)
        score += alpha_count
        score += min(len(nonempty_values), expected_width) / 2

        first = values[0] if values else ""
        if date_like(first) or numeric_like(first):
            score -= 8
        elif re.search(r"[A-Za-z]", first):
            score += 4

        if len(row) == expected_width:
            score += 3
        elif len(row) >= expected_width:
            score += 1
        else:
            score -= (expected_width - len(row)) * 0.5

        for following in parsed[index + 1:index + 4]:
            if nonempty(following):
                if following and date_like(following[0]):
                    score += 6
                break

        return score

    candidates = [
        (index, row)
        for index, row in enumerate(parsed)
        if nonempty(row)
    ]

    if not candidates:
        return {"columns": [], "rows": []}

    header_index, header_row = max(
        candidates,
        key=lambda item: header_score(item[0], item[1]),
    )

    def normalize(row):
        values = [str(value) for value in row]
        if len(values) < expected_width:
            return values + [""] * (expected_width - len(values))
        if len(values) > expected_width:
            return values[:expected_width - 1] + [
                delimiter.join(values[expected_width - 1:])
            ]
        return values

    columns = normalize(header_row)
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = []
    for row in parsed[header_index + 1:]:
        if not nonempty(row):
            continue
        rows.append(normalize(row))

    return {"columns": columns, "rows": rows}
